const ORDER: TargetLanguage[] = ["es", "zh", "hi", "pt", "fr", "ja", "ko"];

function build(): Record<TargetLanguage, Record<string, string>> {
  const tables = Object.fromEntries(ORDER.map((lang) => [lang, {} as Record<string, string>])) as Record<
    TargetLanguage,
    Record<string, string>
  >;
  for (const [en, ...translations] of ROWS) {
    ORDER.forEach((lang, index) => {
      tables[lang][en] = translations[index];
    });
  }
  return tables;
}

export const MESSAGES = build();

export const PATTERNS = Object.fromEntries(
  ORDER.map((lang, index) => [lang, PATTERN_ROWS.map(([pattern, ...translations]): [RegExp, string] => [pattern, translations[index]])]),
) as unknown as Record<TargetLanguage, readonly [RegExp, string][]>;
